mutation_contracts.query:
mutation MappedUpdateFileUpload($filename: String, $id: Int) {
  update_file_upload(filename: $filename, id: $id) {
    id
  }
}

read_services.query:
query HeroTasks($first: Int!, $offset: Int!) {
  tasks(first: $first, offset: $offset, orderBy: "id") {
    author_user_id
    company_id
    target_user_id
    title
    comment
    target_project_match_id
    due_date
    done_date
    created
    modified
    start
    end
    is_deleted
    id
    author {
      id
    }
    target_project_match {
      id
      name
      project_title
    }
    target_user {
      id
      partner {
        full_name
      }
    }
  }
}

query DirectHeroDocuments($first: Int!, $offset: Int!) {
  FileUpload_FileUploads(first: $first, offset: $offset, sortings: [ID_ASC]) {
    edges {
      node {
        category
        created
        downloadUrl
        filename
        id
        modified
        size
        uuid
        imageCategory
        section
        type
        companyId
        projectId
      }
    }
  }
}

query DirectHeroPictures($first: Int!, $offset: Int!) {
  FileUpload_FileUploads(
    first: $first
    offset: $offset
    sortings: [ID_ASC]
    filters: {category: {equals: "images"}}
  ) {
    edges {
      node {
        category
        created
        downloadUrl
        filename
        id
        modified
        size
        uuid
        imageCategory
        section
        type
        companyId
        projectId
      }
    }
  }
}

query DirectHeroEmployees {
  company {
    partners {
      account_type
      email
      first_name
      full_name
      id
      last_name
      mobile
      phone
      role
      status
      user {
        created
        email
        id
        last_login
        locale
        modified
        role
      }
      user_id
      address {
        full_address
        id
      }
      birth_date
      company_branches {
        created
        id
        marker_color
        modified
        name
        radius
      }
      created
      fax
      modified
      no_signature
      profile_image {
        filename
        id
      }
      signature
      signature_image {
        filename
        id
      }
      title
      company {
        id
        name
      }
      company_id
      initial_last_name
      name
    }
  }
}
